// Rebuilt again: the previous version required every field in one exact
// fixed order, which only matched 2 of 15 real listings. This version
// finds each card's boundary independently (marked by "Solicitation #:")
// and looks up each field on its own within that boundary - so a listing
// missing "Goals" or with fields in a different order still parses fully.

const raw = $input.first().json.data || $input.first().json.body || '';

const hrefMatches = [...raw.matchAll(/href="([^"]+)"[^>]*>\s*View the full details for this opportunity/gi)]
  .map(m => m[1]);

const text = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, '\n')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

const marker = /Solicitation #:?/gi;
const positions = [];
let mm;
while ((mm = marker.exec(text)) !== null) positions.push(mm.index);

function field(chunk, label) {
  const m = chunk.match(new RegExp(label + '\\s*:?\\s*\\n?\\s*([^\\n]+)', 'i'));
  return m ? m[1].trim() : '';
}

const LABEL_LINE = /^(Solicitation #|Issue Date|Due Date|Classification|Location|Type|Goals|Status)\s*:?/i;

const results = [];
for (let i = 0; i < positions.length; i++) {
  const chunkStart = positions[i];
  const chunkEnd = i + 1 < positions.length ? positions[i + 1] : text.length;
  const chunk = text.slice(chunkStart, chunkEnd);

  // Title sits just above "Solicitation #:" - scan backward through the
  // text before this card for the last line that isn't itself a field label.
  const priorStart = i === 0 ? 0 : positions[i - 1];
  const beforeLines = text.slice(priorStart, chunkStart).split('\n').map(l => l.trim()).filter(Boolean);
  let title = '';
  for (let li = beforeLines.length - 1; li >= 0; li--) {
    if (!LABEL_LINE.test(beforeLines[li]) && beforeLines[li].length > 3) { title = beforeLines[li]; break; }
  }

  const solMatch = chunk.match(/Solicitation #:?\s*([^\n]+)/i);
  const solicitation = solMatch ? solMatch[1].trim() : '';
  if (!solicitation) continue;

  results.push({
    json: {
      _rawSource: 'DASNY',
      solicitationNumber: solicitation,
      projectNameGuess: title,
      issueDate: field(chunk, 'Issue Date'),
      dueDate: field(chunk, 'Due Date'),
      classification: field(chunk, 'Classification'),
      locationRaw: field(chunk, 'Location'),
      typeField: field(chunk, 'Type'),
      goals: field(chunk, 'Goals'),
      statusRaw: field(chunk, 'Status'),
      detailUrl: hrefMatches[i] ? (hrefMatches[i].startsWith('http') ? hrefMatches[i] : `https://www.dasny.org${hrefMatches[i]}`) : ''
    }
  });
}

return results.length ? results : [{
  json: { _parseFailed: true, _rawSource: 'DASNY', _note: 'Zero listings parsed - check raw fetch output directly.' }
}];

const listing = $('A3. One Listing at a Time').first().json;
const raw = $input.first().json.data || $input.first().json.body || '';

const text = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, '\n')
  .replace(/&nbsp;/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

// Many sites hide emails from plain fetches using Cloudflare's email
// obfuscation - the real address is scrambled as hex in a data-cfemail
// attribute and only unscrambled by a script running in a real browser
// (which is why it looked fine in a screenshot but shows blank here).
// This decodes it - it's a publicly documented encoding, not a bypass of
// any access control, the same category as decoding HTML entities.
function decodeCfEmail(encoded) {
  try {
    const r = parseInt(encoded.substr(0, 2), 16);
    let email = '';
    for (let n = 2; n < encoded.length; n += 2) {
      email += String.fromCharCode(parseInt(encoded.substr(n, 2), 16) ^ r);
    }
    return email;
  } catch (e) { return ''; }
}
function findEmail(htmlChunk, textChunk) {
  const cfMatch = htmlChunk.match(/data-cfemail="([a-f0-9]+)"/i);
  if (cfMatch) {
    const decoded = decodeCfEmail(cfMatch[1]);
    if (decoded.includes('@')) return decoded;
  }
  const plain = textChunk.match(/[\w.+-]+@[\w-]+\.[\w.]{2,}/);
  return plain ? plain[0] : '';
}

let contactPerson = '', contactPhone = '', contactEmail = '', submitToEmail = '';

const primaryTextMatch = text.match(/Primary Contact([\s\S]*?)Submit To Contact/i);
const primaryHtmlStart = raw.search(/Primary Contact/i);
const primaryHtmlEnd = raw.search(/Submit To Contact/i);
const primaryHtmlBlock = (primaryHtmlStart >= 0 && primaryHtmlEnd > primaryHtmlStart) ? raw.slice(primaryHtmlStart, primaryHtmlEnd) : '';

if (primaryTextMatch) {
  const block = primaryTextMatch[1].trim();
  const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
  contactPerson = lines[0] || '';
  const phoneMatch = block.match(/Phone:\s*(\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4})/i);
  contactPhone = phoneMatch ? phoneMatch[1] : '';
  contactEmail = findEmail(primaryHtmlBlock, block);
}

const submitHtmlStart = raw.search(/Submit To Contact/i);
const submitHtmlBlock = submitHtmlStart >= 0 ? raw.slice(submitHtmlStart, submitHtmlStart + 3000) : '';
const submitTextMatch = text.match(/Submit To Contact([\s\S]{0,400})/i);
submitToEmail = findEmail(submitHtmlBlock, submitTextMatch ? submitTextMatch[1] : '');

// Last-resort fallback: if the structured block didn't parse at all, grab
// any real (non-cloudflare-hidden) email visible anywhere on the page.
if (!contactEmail) {
  const anyEmail = text.match(/[\w.+-]+@[\w-]+\.[\w.]{2,}/);
  if (anyEmail && !/noreply|webmaster/i.test(anyEmail[0])) contactEmail = anyEmail[0];
}

const preBidMatch = text.match(/Pre-?Bid Meeting(?: will be held on| ?:)?\s*([A-Za-z]+ \d{1,2},? \d{4}|\d{1,2}\/\d{1,2}\/\d{2,4})/i);
const preBidDate = preBidMatch ? preBidMatch[1] : '';

const valueMatch = text.match(/(?:Estimated (?:Value|Cost)|Contract (?:Value|Amount)|Engineer'?s Estimate)[^\n$]{0,40}(\$[\d,.]+\s*(?:[MK]|million|thousand)?(?:\s*-\s*\$[\d,.]+\s*[MK]?)?)/i);
const estimatedValue = valueMatch ? valueMatch[1] : '';

const docLinks = [...raw.matchAll(/href="([^"]+\.(?:pdf|docx))"/gi)].map(m => m[1]).slice(0, 10);

return [{
  json: {
    ...listing,
    contactPerson, contactPhone, contactEmail, submitToEmail,
    preBidDate, estimatedValue,
    bidDocuments: docLinks.join(', ')
  }
}];

// PDF data only fills gaps the HTML page left blank - it never overwrites
// what the HTML page's structured Contacts block already gave us, since
// that's a reliable fixed structure and free-text PDF extraction isn't.

const htmlRow = $('A6. Parse Contacts + Details').first().json;

let extracted = {};
try {
  const raw = $json.choices[0].message.content;
  const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  extracted = JSON.parse(match ? match[0] : clean);
} catch (e) { extracted = {}; }

return [{
  json: {
    ...htmlRow,
    contactPerson: htmlRow.contactPerson || extracted.contactPerson || '',
    contactEmail: htmlRow.contactEmail || extracted.contactEmail || '',
    contactPhone: htmlRow.contactPhone || extracted.contactPhone || '',
    estimatedValue: htmlRow.estimatedValue || extracted.estimatedValue || '',
    preBidDate: htmlRow.preBidDate || extracted.preBidDate || ''
  }
}];

const cityCountyMap = {
  JAMAICA: 'Queens', FLUSHING: 'Queens', BRONX: 'Bronx', BUFFALO: 'Erie',
  SYRACUSE: 'Onondaga', ALBANY: 'Albany', BROOKLYN: 'Kings', MANHATTAN: 'New York',
  'NEW YORK': 'New York', ROCHESTER: 'Monroe', YONKERS: 'Westchester'
};

const r = $json;
const today = new Date().toISOString().slice(0, 10);

function toIso(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
}

function extractCounty(locationText) {
  const upper = (locationText || '').toUpperCase();
  for (const city of Object.keys(cityCountyMap)) {
    if (upper.includes(city)) return cityCountyMap[city];
  }
  return '';
}

const bidDateIso = toIso(r.dueDate);

return [{
  json: {
    "Project ID": r.solicitationNumber,
    "Project Name": r.projectNameGuess || '',
    "Agency": "DASNY",
    "Project Type": r.classification || '',
    "Location": r.locationRaw || '',
    "County": extractCounty(r.locationRaw),
    "Project Stage": r.statusRaw || '',
    "Estimated Value": r.estimatedValue || '',
    "Bid Date": bidDateIso,
    "Pre-Bid Date": r.preBidDate || '',
    "Contractor Type": 'GC',
    "Trade": r.typeField || '',
    "Solicitation #": r.solicitationNumber,
    "Project URL": r.detailUrl || '',
    "Bid Documents": r.bidDocuments || '',
    "Contact Person": r.contactPerson || '',
    "Contact Phone": r.contactPhone || '',
    "Contact Email": r.contactEmail || '',
    "Submit To Email": r.submitToEmail || '',
    "Status": bidDateIso ? (bidDateIso >= today ? 'Open' : 'Closed') : (r.statusRaw || ''),
    "Previous Status": '',
    "Last Checked": new Date().toISOString(),
    "Last Updated": new Date().toISOString(),
    "Change Detected": 'No',
    "Source": 'DASNY',
    "isParseError": false
  }
}];

const countyMap = { MANHATTAN: 'New York', BROOKLYN: 'Kings', BRONX: 'Bronx', QUEENS: 'Queens', 'STATEN ISLAND': 'Richmond', 'STATEN IS': 'Richmond' };

let records = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) records.push(...item.json);
  else records.push(item.json);
}
if (!records.length) {
  return [{ json: { _parseFailed: true, _rawSource: 'NYCSCA-Anticipated', _note: 'API returned zero records.' } }];
}

return records.map(r => {
  const boro = (r.upcoming_project_borough || '').trim().toUpperCase();
  return {
    json: {
      "Project ID": `SCA-${r.upcoming_project_design_number || 'NA'}-${r.upcoming_project_category || ''}`.replace(/\s+/g, '_'),
      "Project Name": r.upcoming_project_name || r.upcoming_project_description || '',
      "Agency": "NYC SCA",
      "Project Type": "School",
      "Location": boro ? `${boro.charAt(0)}${boro.slice(1).toLowerCase()}, NY` : '',
      "County": countyMap[boro] || boro,
      "Project Stage": "Upcoming",
      "Estimated Value": r.upcoming_project_design_completion_date || '',
      "Bid Date": '', "Pre-Bid Date": '', "Contractor Type": 'GC',
      "Trade": r.upcoming_project_category || '',
      "Solicitation #": '',
      "Project URL": 'https://data.cityofnewyork.us/d/tsak-vtv3',
      "Bid Documents": '',
      "Contact Person": '', "Contact Email": '', "Submit To Email": '',
      "Status": "Upcoming", "Previous Status": '',
      "Last Checked": new Date().toISOString(), "Last Updated": new Date().toISOString(),
      "Change Detected": 'No', "Source": 'NYCSCA', "isParseError": false
    }
  };
});

// Confirmed real fields (from an actual node output screenshot):
// name, boro, geo_dist, projdesc, award, constype, buildingid,
// building_address, city, zip_code, borough
//
// No contractor or contact field exists anywhere in this dataset - that's
// not a mapping bug, it's genuinely absent from what NYC publishes here.
// Contact Person/Email stay honestly blank for this source, same as the
// Anticipated Awards dataset.

const countyMap = { MANHATTAN: 'New York', BROOKLYN: 'Kings', BRONX: 'Bronx', QUEENS: 'Queens', 'STATEN ISLAND': 'Richmond', 'STATEN IS': 'Richmond' };

let records = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) records.push(...item.json);
  else records.push(item.json);
}
if (!records.length) {
  return [{ json: { _parseFailed: true, _rawSource: 'NYCSCA-Active', _note: 'API returned zero records.' } }];
}

return records.map(r => {
  const boroFull = (r.borough || '').trim().toUpperCase();
  const address = [r.building_address, r.city, r.zip_code].filter(Boolean).join(', ');

  return {
    json: {
      "Project ID": `SCA-ACTIVE-${r.buildingid || 'NA'}`.replace(/\s+/g, '_'),
      "Project Name": r.name || '',
      "Agency": "NYC SCA",
      "Project Type": r.constype || 'School',
      "Location": address || (r.city ? `${r.city}, NY` : ''),
      "County": countyMap[boroFull] || r.borough || '',
      "Project Stage": "Under Construction",
      "Estimated Value": r.award || '',
      "Bid Date": '', "Pre-Bid Date": '',
      "Contractor Type": 'GC',
      "Trade": r.projdesc || '',
      "Solicitation #": '',
      "Project URL": 'https://data.cityofnewyork.us/d/8586-3zfm',
      "Bid Documents": '',
      "Contact Person": '', "Contact Email": '', "Submit To Email": '',
      "Status": "Under Construction", "Previous Status": '',
      "Last Checked": new Date().toISOString(), "Last Updated": new Date().toISOString(),
      "Change Detected": 'No', "Source": 'NYCSCA-Active', "isParseError": false
    }
  };
});

// Human-in-the-loop CAPTCHA handling: detect common indicators and STOP -
// never attempt to solve, defeat, or work around a CAPTCHA. This is the
// legitimate pattern for a real bid-monitoring product: flag it for a
// person to check manually, and keep every other source running normally.

const raw = $input.first().json.data || $input.first().json.body || '';
const lower = raw.toLowerCase();
const INDICATORS = ['captcha', 'recaptcha', 'hcaptcha', 'verify you are human', 'are you a robot', 'cloudflare challenge', 'checking your browser'];

const hit = INDICATORS.find(kw => lower.includes(kw));
return [{ json: { ...$json, captchaDetected: !!hit, captchaIndicator: hit || '' } }];

let inputData = '';
if ($input.first().json.data) { inputData = $input.first().json.data; }
else if ($input.first().json) { inputData = $input.first().json; }

let sourceUrl = '';
if ($('D3. Loop Each Website').item.json.URL) { sourceUrl = $('D3. Loop Each Website').item.json.URL; }

let agency = 'Unknown Agency';
if ($('D3. Loop Each Website').item.json['Source Name']) { agency = $('D3. Loop Each Website').item.json['Source Name']; }
else if ($('D3. Loop Each Website').item.json.Agency) { agency = $('D3. Loop Each Website').item.json.Agency; }

if ($input.first().json.statusCode >= 400) {
  return [{ json: { agency: agency, sourceUrl: sourceUrl, isJsonApi: false, candidates: [] } }];
}

let isJsonApi = false;
let html = '';

if (typeof inputData === 'object') {
  isJsonApi = true;
  html = JSON.stringify(inputData);
} else if (typeof inputData === 'string' && (inputData.trim().startsWith('[{') ? true : inputData.trim().startsWith('{'))) {
  isJsonApi = true;
  html = inputData;
} else {
  html = inputData;
}

if (isJsonApi) {
  if (html.includes('Not found')) { return [{ json: { agency: agency, sourceUrl: sourceUrl, isJsonApi: true, candidates: [] } }]; }
  if (html.includes('error')) { return [{ json: { agency: agency, sourceUrl: sourceUrl, isJsonApi: true, candidates: [] } }]; }
  return [{ json: { agency: agency, sourceUrl: sourceUrl, isJsonApi: true, candidates: [{ text: 'JSON API Source', url: sourceUrl }] } }];
}

let baseUrl = '';
try { baseUrl = new URL(sourceUrl).origin; } catch(e) {}

const linkMatches = [...html.matchAll(/<a\s+(?:[^>]*?\s+)?href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi)];
const candidates = [];
const seenUrls = new Set();

for (const match of linkMatches) {
  let href = match[1].trim();
  let text = match[2].replace(/<[^>]+>/g, '').trim();

  if (!href) continue;
  if (href.startsWith('#')) continue;
  if (href.startsWith('javascript:')) continue;

  if (!href.startsWith('http')) {
     href = href.startsWith('/') ? baseUrl + href : sourceUrl.replace(/\/[^\/]*$/, '/') + href;
  }

  const lowerHref = href.toLowerCase();
  if (lowerHref.match(/facebook|twitter|linkedin|\.css|\.js|\.png|\.jpg/)) continue;

  if (!seenUrls.has(href)) {
    seenUrls.add(href);
    let finalText = text ? text : 'Link';
    candidates.push({ text: finalText, url: href });
  }
}

return [{ json: { agency: agency, sourceUrl: sourceUrl, isJsonApi: false, candidates: candidates.slice(0, 15) } }];

let inputJson = {};
if ($input.first() && $input.first().json) { inputJson = $input.first().json; }

let candidatesData = {};
if ($('D6a. Pre-Extract Candidate Links').first() && $('D6a. Pre-Extract Candidate Links').first().json) {
    candidatesData = $('D6a. Pre-Extract Candidate Links').first().json;
}

let agency = candidatesData.agency || 'Unknown Agency';
let candidates = candidatesData.candidates || [];
const realUrls = new Set(candidates.map(c => c.url));
let bids = [];

if (candidatesData.isJsonApi && candidates.length > 0) {
  bids = [{ solicitationNumber: 'API-DATA', projectName: 'API Source Data', url: candidates[0].url }];
} else {
  let rawOutput = inputJson.output || inputJson.text || '';
  if (rawOutput) {
    try {
      let cleanStr = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
      const match = cleanStr.match(/\[[\s\S]*\]/);
      if (match) cleanStr = match[0];
      const parsed = JSON.parse(cleanStr);
      if (Array.isArray(parsed) && parsed.length > 0) {
        // Hallucination guard: an LLM can return perfectly valid-looking JSON
        // with a URL it invented rather than one that's actually on the page
        // (seen in practice: a fabricated "procurement.example.gov" bid).
        // Only accept a bid whose URL genuinely came from this page's real
        // extracted links - anything else gets silently dropped, not written.
        bids = parsed.filter(b => b.url && realUrls.has(b.url));
      }
    } catch(e) {}
  }

  if (bids.length === 0 && candidates.length > 0) {
    const keywords = ['bid', 'solicitation', 'rfp', 'contract', 'opportunity', 'project', '.pdf'];
    const relevant = candidates.filter(c => keywords.some(k => (c.text + c.url).toLowerCase().includes(k)));
    const selected = relevant.length > 0 ? relevant.slice(0, 5) : [];
    bids = selected.map((c, idx) => ({ solicitationNumber: `BID-${idx + 1}`, projectName: c.text, url: c.url }));
  }
}

// Honest failure signal (the pasted version never set this, so failures
// never reached the Errors tab) - if nothing was found, say so.
if (bids.length === 0) {
  return [{ json: { _isEmpty: "true", agency: agency, _parseFailed: true,
    _rawSource: agency, _note: 'No bid links found on this page - check D6a output directly, or this source may need Method=API/HTML if it has a fixed structure.' } }];
}

return bids.map((b, idx) => ({
  json: {
    _isEmpty: "false",
    agency: agency,
    solicitationNumber: b.solicitationNumber || b.solNum || b.id || `SOL-${idx + 1}`,
    projectName: b.projectName || b.name || b.title || 'Construction Bid',
    url: b.url || b.link || b.pdfUrl || ''
  }
}));

// Contact info often lives on the HTML page itself, but sites also
// frequently link out to a spec/RFP PDF with additional detail. Rather than
// choosing HTML *or* PDF, this finds the first real PDF link on the detail
// page so we can pull its text in too - both sources feed the AI together.

const raw = $input.first().json.data || $input.first().json.body || '';
const match = raw.match(/href="([^"]+\.pdf)"/i);

if (!match) return [{ json: { hasLinkedPdf: false, pdfUrl: '', htmlText: raw } }];

let pdfUrl = match[1];
if (!pdfUrl.startsWith('http')) {
  try {
    const base = new URL($('D8. Loop Specific Bids').item.json.url).origin;
    pdfUrl = pdfUrl.startsWith('/') ? base + pdfUrl : base + '/' + pdfUrl;
  } catch (e) { return [{ json: { hasLinkedPdf: false, pdfUrl: '', htmlText: raw } }]; }
}
return [{ json: { hasLinkedPdf: true, pdfUrl, htmlText: raw } }];

// Combines whichever text sources actually ran for this bid:
//  - direct-PDF path: this item's own .text (from D11a)
//  - HTML path: D10c's carried-forward htmlText, plus D10f's linked-PDF
//    text if a PDF was found and successfully read
// Using node-name lookups (not relying on multiple raw connections to
// merge automatically) is what makes this actually combine both sources
// for the same bid instead of firing twice with half the picture each.

function safeFirst(nodeName) {
  try { return $(nodeName).first().json; } catch (e) { return null; }
}

const d10c = safeFirst('D10c. Find PDF Links on Detail Page');
let combinedText = '';

if (d10c) {
  // HTML path (came through D10b -> D10c)
  combinedText += (d10c.htmlText || '') + '\n\n';
  // If a linked PDF was found and this execution is the one that read it,
  // $json.text here is that PDF's extracted text - add it too.
  const linkedPdfText = $json.text;
  if (typeof linkedPdfText === 'string') combinedText += linkedPdfText + '\n\n';
} else {
  // Direct-PDF path (came through D10a -> D11a) or its error fallback
  const directText = $json.text || $json.data || '';
  combinedText += (typeof directText === 'string' ? directText : JSON.stringify(directText)) + '\n\n';
}

combinedText = combinedText.substring(0, 100000);
return [{ json: { text: combinedText } }];

let base = {};
if ($('D8. Loop Specific Bids').item.json) { base = $('D8. Loop Specific Bids').item.json; }

let contactEmail = '', contactName = '', contactPhone = '', estimatedValue = '', preBidDate = '', bidDate = '', location = '', trade = '';
let aiRaw = '';
let aiCallFailed = false;

try { aiRaw = $input.first().json.output; } catch(e) { aiCallFailed = true; }

if (aiRaw) {
  try {
    let cleanJsonStr = aiRaw.replace(/```json/gi, '').replace(/```/g, '').trim();
    const match = cleanJsonStr.match(/\{[\s\S]*\}/);
    if (match) cleanJsonStr = match[0];
    const ext = JSON.parse(cleanJsonStr);
    contactEmail = ext.contactEmail || '';
    contactName = ext.contactPerson || '';
    contactPhone = ext.contactPhone || '';
    estimatedValue = ext.estimatedValue || '';
    preBidDate = ext.preBidDate || '';
    bidDate = ext.bidDate || '';
    location = ext.location || '';
    trade = ext.trade || '';
  } catch(e) { aiCallFailed = true; }
} else {
  aiCallFailed = true;
}

const pId = base.solicitationNumber || '001';
const now = new Date().toISOString();

// Fallback: if the AI call itself failed (not just found nothing), a plain
// regex over the same document text still catches an email if one is
// visibly present - this is what keeps "the AI call errored" from meaning
// "we lost the contact info entirely" for your priority field.
let rawDocText = '';
try { rawDocText = $('D12. Prepare Text for AI').first().json.text || ''; } catch(e) {}
if (!contactEmail && rawDocText) {
  const anyEmail = rawDocText.match(/[\w.+-]+@[\w-]+\.[\w.]{2,}/);
  if (anyEmail && !/noreply|webmaster|example\.com/i.test(anyEmail[0])) contactEmail = anyEmail[0];
}

return [{ json: {
  "Project ID": `${base.agency}-${pId}`,
  "Project Name": base.projectName || 'Construction Bid',
  "Agency": base.agency,
  "Project Type": trade || '',
  "Location": location,
  "County": "",
  "Project Stage": "Open",
  "Estimated Value": estimatedValue,
  "Bid Date": bidDate,
  "Pre-Bid Date": preBidDate,
  "Contractor Type": "GC",
  "Trade": trade,
  "Solicitation #": pId,
  "Project URL": base.url,
  "Bid Documents": base.url,
  "Contact Person": contactName,
  "Contact Phone": contactPhone,
  "Contact Email": contactEmail,
  "Submit To Email": contactEmail,
  "Status": "Open",
  "Previous Status": "",
  "Last Checked": now,
  "Last Updated": now,
  "Change Detected": "No",
  "Source": base.agency,
  // Honest signal: if the AI call itself failed, flag it instead of
  // silently writing a mostly-empty row that looks like a real bid.
  "isParseError": aiCallFailed
} }];

// Confirmed real structure (from a live screenshot): each ad card has a
// title, then a "CR#:" line, then Company/Issue date/Due date/Category/
// Ad type - same per-card-boundary approach as DASNY, since fields can
// vary in presence/order between ad types (general ads vs subcontracting
// opportunity ads look slightly different).

const raw = $input.first().json.data || $input.first().json.body || '';

const text = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, '\n')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

const marker = /CR#:?/gi;
const positions = [];
let mm;
while ((mm = marker.exec(text)) !== null) positions.push(mm.index);

function field(chunk, label) {
  const m = chunk.match(new RegExp(label + '\\s*:?\\s*\\n?\\s*([^\\n]+)', 'i'));
  return m ? m[1].trim() : '';
}
const LABEL_LINE = /^(CR#|Company|Issue date|Due date|Category|Ad type|Title)\s*:?/i;

const results = [];
for (let i = 0; i < positions.length; i++) {
  const chunkStart = positions[i];
  const chunkEnd = i + 1 < positions.length ? positions[i + 1] : text.length;
  const chunk = text.slice(chunkStart, chunkEnd);

  const crMatch = chunk.match(/CR#:?\s*([^\n]+)/i);
  const crNumber = crMatch ? crMatch[1].trim() : '';
  if (!crNumber) continue;

  const priorStart = i === 0 ? 0 : positions[i - 1];
  const beforeLines = text.slice(priorStart, chunkStart).split('\n').map(l => l.trim()).filter(Boolean);
  let title = '';
  for (let li = beforeLines.length - 1; li >= 0; li--) {
    if (!LABEL_LINE.test(beforeLines[li]) && beforeLines[li].length > 5
        && !/^This is a/i.test(beforeLines[li])) { title = beforeLines[li]; break; }
  }

  results.push({
    json: {
      _rawSource: 'NYSCR',
      crNumber,
      title: title || 'NYSCR Opportunity',
      company: field(chunk, 'Company'),
      issueDate: field(chunk, 'Issue date'),
      dueDate: field(chunk, 'Due date'),
      category: field(chunk, 'Category'),
      adType: field(chunk, 'Ad type')
    }
  });
}

return results.length ? results : [{
  json: { _parseFailed: true, _rawSource: 'NYSCR', _note: 'Zero ads parsed - check raw fetch output; the search page may need a query parameter to show results by default.' }
}];

const r = $json;
if (r._parseFailed) return [{ json: r }];  // preserve the failure signal, don't normalize garbage

const now = new Date().toISOString();

function toIso(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
}

return [{
  json: {
    "Project ID": `CR-${r.crNumber}`,
    "Project Name": r.title || '',
    "Agency": r.company || 'NYS (varies)',
    "Project Type": r.category || '',
    "Location": '',
    "County": '',
    "Project Stage": 'Open',
    "Estimated Value": '',
    "Bid Date": toIso(r.dueDate),
    "Pre-Bid Date": '',
    "Contractor Type": 'GC',
    "Trade": r.category || '',
    "Solicitation #": r.crNumber,
    "Project URL": 'https://www.nyscr.ny.gov/Ads/Search',
    "Bid Documents": '',
    // Genuinely not available without logging in - not a parsing gap.
    "Contact Person": '', "Contact Email": '', "Submit To Email": '',
    "Status": 'Open', "Previous Status": '',
    "Last Checked": now, "Last Updated": now,
    "Change Detected": 'No', "Source": 'NYSCR', "isParseError": false
  }
}];

const TRADE_KEYWORDS = ['ROOFING', 'ELECTRICAL', 'HVAC', 'PLUMBING', 'BOILER', 'MASONRY', 'EXT. WORK', 'GC'];
const today = new Date().toISOString().slice(0, 10);

function parseMidpoint(rangeStr) {
  if (!rangeStr) return null;
  const nums = (rangeStr.match(/[\d.]+/g) || []).map(Number);
  const mult = /M/i.test(rangeStr) ? 1_000_000 : (/K/i.test(rangeStr) ? 1_000 : 1);
  if (nums.length === 2) return ((nums[0] + nums[1]) / 2) * mult;
  if (nums.length === 1) return nums[0] * mult;
  return null;
}

return $input.all().map(item => {
  const row = item.json;
  if (row.isParseError || row._parseFailed) return { json: { ...row, isParseError: true } };

  let score = 0;
  if (row['Bid Date']) {
    const days = Math.floor((new Date(row['Bid Date']) - new Date(today)) / 86400000);
    if (days >= 0 && days <= 14) score += 25;
    else if (days <= 30) score += 15;
    else if (days <= 60) score += 5;
  }
  const midpoint = parseMidpoint(row['Estimated Value']);
  if (midpoint !== null) {
    if (midpoint >= 5_000_000) score += 25;
    else if (midpoint >= 1_000_000) score += 15;
    else score += 5;
  }
  if (row['Source'] === 'NYCSCA') score += 20;
  else if (row['Source'] === 'DASNY') score += 15;

  const haystack = `${row['Trade'] || ''} ${row['Project Name'] || ''}`.toUpperCase();
  let tradeBonus = 0;
  for (const kw of TRADE_KEYWORDS) {
    if (haystack.includes(kw)) tradeBonus = Math.max(tradeBonus, 30);
  }
  score += tradeBonus;

  if (row['Contact Email']) score += 10;
  if (row['Pre-Bid Date']) score += 5;

  return { json: { ...row, "Opportunity Score": Math.min(100, score), isParseError: false } };
});

const freshRows = $('C3. Split Errors vs Good Rows').all().map(i => i.json);
const existingRows = $('C5. Read Existing Bids').all().map(i => i.json);

const existingById = {};
for (const row of existingRows) if (row['Project ID']) existingById[row['Project ID']] = row;

const KEY_FIELDS = ['Bid Date', 'Estimated Value', 'Status', 'Contact Email'];

return freshRows.map(row => {
  const prior = existingById[row['Project ID']];
  if (!prior) return { json: { ...row, "Change Detected": 'Yes', "Previous Status": '' } };
  const changed = KEY_FIELDS.some(f => String(prior[f] || '') !== String(row[f] || ''));
  return { json: { ...row, "Change Detected": changed ? 'Yes' : 'No',
    "Previous Status": changed ? (prior['Status'] || '') : (prior['Previous Status'] || '') } };
});

function safeAll(nodeName) { try { return $(nodeName).all(); } catch (e) { return []; } }
const goodRows = safeAll('C6. Compare + Set Change Detected');
const errorRows = safeAll('C4. Log Errors');

const bySource = {};
for (const item of goodRows) { const s = item.json.Source || 'Unknown'; bySource[s] = (bySource[s] || 0) + 1; }

return [{ json: {
  "Run Time": new Date().toISOString(),
  "Total Rows Written": goodRows.length,
  "Rows Per Source": JSON.stringify(bySource),
  "Parse Errors": errorRows.length,
  "Changed Rows": goodRows.filter(i => i.json['Change Detected'] === 'Yes').length
}}];
